#include <algorithm>
int longest_rise(std::vector<int> history) {
    if (history.empty()) return 0;
    int run = 1, best = 1;
    for (std::size_t index = 1; index < history.size(); ++index) {
        run = history[index] > history[index - 1] ? run + 1 : 1;
        best = std::max(best, run);
    }
    return best;
}

