#include <string>
#include <string_view>
bool balanced_brackets(std::string_view input) {
    std::string stack;
    for (char c : input) {
        if (c == '(' || c == '[' || c == '{') stack += c;
        if (c == ')' || c == ']' || c == '}') {
            if (stack.empty()) return false;
            char open = stack.back();
            if ((c == ')' && open != '(') || (c == ']' && open != '[')
                || (c == '}' && open != '{')) return false;
            stack.pop_back();
        }
    }
    return stack.empty();
}

