#include <map>
#include <istream>
#include <string>
auto ledger(std::istream& in) {
    using Key = std::string;
    std::map<Key, int> amounts;
    std::string name;
    int amount;
    while (in >> name >> amount) amounts[name] += amount;
    for (auto it = amounts.begin(); it != amounts.end();) {
        if (it->second == 0) it = amounts.erase(it);
        else ++it;
    }
    return amounts;
}

